"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["9377"],{57055(e,t,s){s.d(t,{Ay:()=>o,RM:()=>i});var a=s(74848),n=s(28453);let i=[];function r(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,n.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"beasts-and-fowl--far-beyond-what-human-fart-moralists-could-ever-attain",children:"Beasts and Fowl \u2014 Far Beyond What Human-Fart Moralists Could Ever Attain!"})}),"\n",(0,a.jsxs)(t.blockquote,{children:["\n",(0,a.jsx)(t.p,{children:"2006/9/6 12:44:59"}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Moralists are all a priori-ists. Their most basic argument always hinges on one assumption: humans are not beasts, and the greatest distinction between humans and beasts is that humans have morality. The fact that such an incoherent assumption has sustained thousands of years of moralistic ranting is probably one of humanity's greatest farces!"}),"\n",(0,a.jsx)(t.p,{children:'"Humans are not beasts" \u2014 this statement can only hold if the concept of "beasts" as used by humans is defined as "not human." That is, the premise for "humans are not beasts" to hold is that humans can define "beasts are not humans." This tautological, human-fart, self-pleasuring logic is the moralists\' most primitive starting point.'}),"\n",(0,a.jsx)(t.p,{children:'As for "the greatest distinction between humans and beasts is that humans have morality," this likewise requires the premise that morality as defined by humans belongs only to humans, and that humans are not beasts. With this same human-fart, self-pleasuring premise, the moralists self-pleasuringly rant: under the morality defined by humans, the greatest distinction between humans and beasts is that humans have morality.'}),"\n",(0,a.jsx)(t.p,{children:"Moralists are nothing but a horde of freaks who get off on ranting. These freaks stubbornly cling to this blade of grass: the world is the world as I define it. Beasts, because moralists define them as non-human, are therefore non-human. Moralists are all Gods of their own making. Even cats yowl in spring. God yowls in spring too. But in the mouths of moralists, the moralist God yowls the spring of morality!"}),"\n",(0,a.jsx)(t.p,{children:"Beasts and fowl \u2014 far beyond what human-fart moralists could ever attain! Even by the moralists' own definition of \"beasts,\" in the presence of real beasts, humans are more beastly than beasts. And the greatest beast of all is that beast greater even than the beast called God \u2014 the moralist himself. Conversely, even by the moralists' own definition of morality, real beasts are the greatest moralists of all. There is nothing more moral in the universe than beasts. And the greatest immoralist is humanity itself. Ask this Earth, look at this Earth's environment, and you'll know what the universe's greatest tumor really is!"}),"\n",(0,a.jsx)(t.p,{children:'Even if you don\'t believe in reincarnation, in the presence of beasts, no human \u2014 moralists included \u2014 has any right to spout any human-fart morality. If you do believe in reincarnation, then humans and beasts are merely fellow travelers cycling through the six realms. Every human has been a beast in countless past lives, and countless beast-incarnations still await you. What right have you to call beasts "beasts"?'}),"\n",(0,a.jsx)(t.p,{children:"Human-fart moralists, don't think that just because you can talk and release a few human farts you can define beasts as beasts. Even if you are dressed to the nines, you are merely \u2014 in the sense of your own beastly definitions \u2014 a beast in fine clothing! You've been climaxing in your self-pleasuring of \"humans are not beasts, the greatest distinction between humans and beasts is that humans have morality\" for several thousand years now. Aren't you tired? Take a rest!"})]})}function o(e={}){let{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(r,{...e})}):r(e)}},48091(e,t,s){s.r(t),s.d(t,{metadata:()=>a,default:()=>d,frontMatter:()=>o,contentTitle:()=>l,toc:()=>u,assets:()=>h});var a=JSON.parse('{"id":"timeline/essays/moralists","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/timeline/essays/moralists.md","sourceDirName":"timeline/essays","slug":"/timeline/essays/moralists","permalink":"/en/timeline/essays/moralists","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"moralists","title":"","hide_table_of_contents":true,"sidebar_label":"Beasts\u2014Far Beyond What Petty Moralists Could Ever Match! (2006/9/6 12:44:59)"},"sidebar":"timelineSidebar","previous":{"title":"Defending Marx 3: Socialism With Either Private Ownership or Market Economy Can Only Be a Fantasy! (2006/9/5 14:13:50)","permalink":"/en/timeline/economics/marx3"},"next":{"title":"Announcement: (2006/9/6 20:05:08)","permalink":"/en/timeline/entertainment/statement0906"}}'),n=s(74848),i=s(28453),r=s(57055);let o={id:"moralists",title:"",hide_table_of_contents:!0,sidebar_label:"Beasts\u2014Far Beyond What Petty Moralists Could Ever Match! (2006/9/6 12:44:59)"},l,h={},u=[...r.RM];function m(e){return(0,n.jsx)(r.Ay,{})}function d(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(m,{...e})}):m(e)}},28453(e,t,s){s.d(t,{R:()=>r,x:()=>o});var a=s(96540);let n={},i=a.createContext(n);function r(e){let t=a.useContext(i);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),a.createElement(i.Provider,{value:t},e.children)}}}]);